@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + SocialSecurityNumber : string
}

class Guest {
  + Name : string
  + IsVIP : boolean
}

class Ship {
  + Name : string
  + Decks : int
  + Length : float
  + PassengerCapacity : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : string
  + BookingDate : date
}

class DestinationArea {
  + Name : string
  + SeaName : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "0..*" Cruise
Cruise "1" -- "1..*" Employee
Cruise "0..*" -- "0..*" Guest
Ship "1" -- "0..*" Cruise
Cruise "1" -- "0..*" Booking
TravelAgency "1" -- "0..*" Booking
Cruise "1" -- "1" DestinationArea
Cruise "1" -- "0..*" Show
Cruise "1" -- "0..*" Ticket
Guest "1" -- "0..*" Ticket

@enduml

